(function() {
    'use strict';

    class WashGameAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'WashGame: The Greenwashing Escalation Paradox';
            this.version = '1.1.0';
            this._dsSnaps = [];

            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    briefingKey: 'r1_briefing',
                    decisions: [
                        { id: 'ambition', labelKey: 'r1_ambition_label', options: [
                            { value: 1, labelKey: 'r1_ambition_1', cost: 2.0 },
                            { value: 2, labelKey: 'r1_ambition_2', cost: 1.2 },
                            { value: 3, labelKey: 'r1_ambition_3', cost: 0.5 }
                        ]},
                        { id: 'materiality', labelKey: 'r1_materiality_label', options: [
                            { value: 1, labelKey: 'r1_materiality_1', cost: 0.3 },
                            { value: 2, labelKey: 'r1_materiality_2', cost: 0.1 },
                            { value: 3, labelKey: 'r1_materiality_3', cost: 0.0 }
                        ]},
                        { id: 'boundary', labelKey: 'r1_boundary_label', options: [
                            { value: 1, labelKey: 'r1_boundary_1', cost: 0.4 },
                            { value: 2, labelKey: 'r1_boundary_2', cost: 0.15 },
                            { value: 3, labelKey: 'r1_boundary_3', cost: 0.05 }
                        ]},
                        { id: 'verification', labelKey: 'r1_verification_label', options: [
                            { value: 1, labelKey: 'r1_verification_1', cost: 0.35 },
                            { value: 2, labelKey: 'r1_verification_2', cost: 0.15 },
                            { value: 3, labelKey: 'r1_verification_3', cost: 0.02 }
                        ]}
                    ]
                },
                {
                    titleKey: 'r2_title',
                    briefingKey: 'r2_briefing',
                    decisions: [
                        { id: 'governance', labelKey: 'r2_governance_label', options: [
                            { value: 1, labelKey: 'r2_governance_1', cost: 0.2 },
                            { value: 2, labelKey: 'r2_governance_2', cost: 0.03 },
                            { value: 3, labelKey: 'r2_governance_3', cost: 0.0 }
                        ]},
                        { id: 'assurance', labelKey: 'r2_assurance_label', options: [
                            { value: 1, labelKey: 'r2_assurance_1', cost: 0.35 },
                            { value: 2, labelKey: 'r2_assurance_2', cost: 0.15 },
                            { value: 3, labelKey: 'r2_assurance_3', cost: 0.02 }
                        ]},
                        { id: 'supplyTransparency', labelKey: 'r2_supply_label', options: [
                            { value: 1, labelKey: 'r2_supply_1', cost: 0.4 },
                            { value: 2, labelKey: 'r2_supply_2', cost: 0.15 },
                            { value: 3, labelKey: 'r2_supply_3', cost: 0.0 }
                        ]},
                        { id: 'auditScope', labelKey: 'r2_audit_label', options: [
                            { value: 1, labelKey: 'r2_audit_1', cost: 0.6 },
                            { value: 2, labelKey: 'r2_audit_2', cost: 0.25 },
                            { value: 3, labelKey: 'r2_audit_3', cost: 0.05 }
                        ]},
                        { id: 'supplierInvest', labelKey: 'r2_supplier_inv_label', options: [
                            { value: 1, labelKey: 'r2_supplier_inv_1', cost: 1.0 },
                            { value: 2, labelKey: 'r2_supplier_inv_2', cost: 0.3 },
                            { value: 3, labelKey: 'r2_supplier_inv_3', cost: 0.0 }
                        ]}
                    ]
                },
                {
                    titleKey: 'r3_title',
                    briefingKey: 'r3_briefing',
                    decisions: [
                        { id: 'publicResponse', labelKey: 'r3_response_label', options: [
                            { value: 1, labelKey: 'r3_response_1', cost: 0.15 },
                            { value: 2, labelKey: 'r3_response_2', cost: 0.03 },
                            { value: 3, labelKey: 'r3_response_3', cost: 0.0 }
                        ]},
                        { id: 'investorOutreach', labelKey: 'r3_outreach_label', options: [
                            { value: 1, labelKey: 'r3_outreach_1', cost: 0.15 },
                            { value: 2, labelKey: 'r3_outreach_2', cost: 0.03 },
                            { value: 3, labelKey: 'r3_outreach_3', cost: 0.0 }
                        ]},
                        { id: 'auditAccel', labelKey: 'r3_audit_label', options: [
                            { value: 1, labelKey: 'r3_audit_1', cost: 0.4 },
                            { value: 2, labelKey: 'r3_audit_2', cost: 0.0 },
                            { value: 3, labelKey: 'r3_audit_3', cost: 0.0 }
                        ]},
                        { id: 'competitivePosture', labelKey: 'r3_posture_label', options: [
                            { value: 1, labelKey: 'r3_posture_1', cost: 1.0 },
                            { value: 2, labelKey: 'r3_posture_2', cost: 0.0 },
                            { value: 3, labelKey: 'r3_posture_3', cost: 0.3 }
                        ]}
                    ]
                },
                {
                    titleKey: 'r4_title',
                    briefingKey: 'r4_briefing',
                    decisions: [
                        { id: 'disclosureFindings', labelKey: 'r4_disclosure_label', options: [
                            { value: 1, labelKey: 'r4_disclosure_1', cost: 0.1 },
                            { value: 2, labelKey: 'r4_disclosure_2', cost: 0.05 },
                            { value: 3, labelKey: 'r4_disclosure_3', cost: 0.0 }
                        ]},
                        { id: 'remediation', labelKey: 'r4_remediation_label', options: [
                            { value: 1, labelKey: 'r4_remediation_1', cost: 0.8 },
                            { value: 2, labelKey: 'r4_remediation_2', cost: 0.8 },
                            { value: 3, labelKey: 'r4_remediation_3', cost: 0.1 }
                        ]},
                        { id: 'thirdPartyVerify', labelKey: 'r4_verify_label', options: [
                            { value: 1, labelKey: 'r4_verify_1', cost: 0.3 },
                            { value: 2, labelKey: 'r4_verify_2', cost: 0.03 },
                            { value: 3, labelKey: 'r4_verify_3', cost: 0.0 }
                        ]}
                    ]
                },
                {
                    titleKey: 'r5_title',
                    briefingKey: 'r5_briefing',
                    decisions: [
                        { id: 'coherence', labelKey: 'r5_coherence_label', options: [
                            { value: 1, labelKey: 'r5_coherence_1', cost: 0.3 },
                            { value: 2, labelKey: 'r5_coherence_2', cost: 0.1 },
                            { value: 3, labelKey: 'r5_coherence_3', cost: 0.0 }
                        ]},
                        { id: 'stakeholderEngage', labelKey: 'r5_engage_label', options: [
                            { value: 1, labelKey: 'r5_engage_1', cost: 0.4 },
                            { value: 2, labelKey: 'r5_engage_2', cost: 0.1 },
                            { value: 3, labelKey: 'r5_engage_3', cost: 0.0 }
                        ]},
                        { id: 'continuousImprove', labelKey: 'r5_improve_label', options: [
                            { value: 1, labelKey: 'r5_improve_1', cost: 0.15 },
                            { value: 2, labelKey: 'r5_improve_2', cost: 0.0 },
                            { value: 3, labelKey: 'r5_improve_3', cost: 0.0 }
                        ]},
                        { id: 'esgFinance', labelKey: 'r5_finance_label', options: [
                            { value: 1, labelKey: 'r5_finance_1', cost: 0.2 },
                            { value: 2, labelKey: 'r5_finance_2', cost: 0.0 },
                            { value: 3, labelKey: 'r5_finance_3', cost: 0.0 }
                        ]},
                        { id: 'publicCommit', labelKey: 'r5_commit_label', options: [
                            { value: 1, labelKey: 'r5_commit_1', cost: 0.3 },
                            { value: 2, labelKey: 'r5_commit_2', cost: 0.05 },
                            { value: 3, labelKey: 'r5_commit_3', cost: 0.0 }
                        ]}
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    esgAuth: 35,
                    regCompliance: 85,
                    ebitdaImpact: 0,
                    brandTrust: 52,
                    budgetRemaining: 5.0,
                    totalBudget: 5.0,
                    esgHistory: [],
                    complianceHistory: [],
                    financeHistory: [],
                    trustHistory: [],
                    eventLog: [],
                    greenwashRisk: 0
                };
                this._dsSnaps = [JSON.parse(JSON.stringify(state.domainState))];
            } else {
                var h = (state.history || []).length;
                if (this._dsSnaps.length > h + 1 && this._dsSnaps[h]) {
                    var snap = JSON.parse(JSON.stringify(this._dsSnaps[h]));
                    var ds0 = state.domainState;
                    for (var k in ds0) { if (!(k in snap)) delete ds0[k]; }
                    for (var k2 in snap) { ds0[k2] = snap[k2]; }
                    this._dsSnaps = this._dsSnaps.slice(0, h + 1);
                }
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var titleText = window.mySimulation ? window.mySimulation.t(round.titleKey) : '';
                var briefText = window.mySimulation ? window.mySimulation.t(round.briefingKey) : '';
                briefEl.innerHTML = '<strong>' + titleText + '</strong><br><br>' + briefText;
            }

            var panel = document.getElementById('decisionsPanel');
            if (!panel) return;
            panel.innerHTML = '';

            var budgetLeft = 5.0;
            if (state.domainState && state.domainState.budgetRemaining !== undefined) {
                budgetLeft = state.domainState.budgetRemaining;
            }

            for (var d = 0; d < round.decisions.length; d++) {
                var dec = round.decisions[d];
                var group = document.createElement('div');
                group.className = 'washgame-decision-group';

                var label = document.createElement('div');
                label.className = 'washgame-decision-label';
                label.setAttribute('data-i18n', dec.labelKey);
                label.textContent = window.mySimulation ? window.mySimulation.t(dec.labelKey) : dec.labelKey;
                group.appendChild(label);

                var optionsDiv = document.createElement('div');
                optionsDiv.className = 'washgame-decision-options';

                for (var o = 0; o < dec.options.length; o++) {
                    var opt = dec.options[o];
                    var btn = document.createElement('button');
                    btn.type = 'button';
                    btn.className = 'washgame-option-btn';
                    btn.setAttribute('data-decision', dec.id);
                    btn.setAttribute('data-value', opt.value);

                    var optLabel = window.mySimulation ? window.mySimulation.t(opt.labelKey) : opt.labelKey;
                    var costText = opt.cost > 0 ? '<span class="washgame-option-cost">' + opt.cost.toFixed(1) + 'M</span>' : '';
                    btn.innerHTML = optLabel + costText;

                    btn.addEventListener('click', function(decId, val) {
                        return function() {
                            var siblings = this.parentNode.querySelectorAll('.washgame-option-btn');
                            for (var s = 0; s < siblings.length; s++) {
                                siblings[s].classList.remove('selected');
                            }
                            this.classList.add('selected');
                        };
                    }(dec.id, opt.value));

                    optionsDiv.appendChild(btn);
                }
                group.appendChild(optionsDiv);
                panel.appendChild(group);
            }

            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) eventPanel.style.display = 'none';
        }

        validateDecisions(decisions) {
            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var totalCost = 0;
            for (var d = 0; d < round.decisions.length; d++) {
                var dec = round.decisions[d];
                var selected = document.querySelector('[data-decision="' + dec.id + '"].selected');
                if (!selected) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warning_select_all'), 'warning'
                    );
                    return false;
                }
                var val = parseInt(selected.getAttribute('data-value'));
                decisions[dec.id] = val;

                var opt = dec.options.find(function(o) { return o.value === val; });
                if (opt) totalCost += opt.cost;
            }

            decisions._roundCost = totalCost;

            var budgetLeft = window.mySimulation.state.domainState.budgetRemaining;
            if (totalCost > budgetLeft + 0.01) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_budget'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var cost = d._roundCost || 0;

            ds.budgetRemaining -= cost;

            var esgDelta = 0;
            var compDelta = 0;
            var finDelta = -cost;
            var trustDelta = 0;
            var eventKey = '';

            if (period === 1) {
                if (d.ambition === 1) { esgDelta += 5; trustDelta += 3; compDelta += 2; }
                else if (d.ambition === 2) { esgDelta += 2; trustDelta += 1; compDelta += 0; }
                else { esgDelta += 0; trustDelta -= 1; compDelta -= 3; ds.greenwashRisk += 15; }

                if (d.materiality === 1) { esgDelta += 2; compDelta += 2; }
                else if (d.materiality === 2) { compDelta += 0; }
                else { compDelta -= 2; ds.greenwashRisk += 5; }

                if (d.boundary === 1) { esgDelta += 2; trustDelta += 2; compDelta += 3; }
                else if (d.boundary === 2) { compDelta += 1; }
                else { compDelta -= 2; ds.greenwashRisk += 10; }

                if (d.verification === 1) { trustDelta += 3; compDelta += 2; }
                else if (d.verification === 2) { trustDelta += 1; compDelta += 1; }
                else { ds.greenwashRisk += 5; }

                if (d.ambition === 1) {
                    eventKey = 'event_1a';
                    trustDelta += 2;
                } else if (d.ambition === 3 && d.materiality === 3) {
                    eventKey = 'event_1c';
                    trustDelta -= 3;
                    ds.greenwashRisk += 5;
                } else {
                    eventKey = 'event_1b';
                    ds.greenwashRisk += 3;
                }
            }

            if (period === 2) {
                if (d.governance === 1) { trustDelta += 3; compDelta += 3; esgDelta += 1; }
                else if (d.governance === 2) { compDelta += 1; }
                else { ds.greenwashRisk += 5; }

                if (d.assurance === 1) { trustDelta += 3; compDelta += 3; }
                else if (d.assurance === 2) { trustDelta += 1; compDelta += 1; }
                else { ds.greenwashRisk += 5; }

                if (d.supplyTransparency === 1) { esgDelta += 3; trustDelta += 2; compDelta += 2; }
                else if (d.supplyTransparency === 2) { trustDelta += 1; }
                else { ds.greenwashRisk += 5; }

                if (d.auditScope === 1) { esgDelta += 2; compDelta += 2; }
                else if (d.auditScope === 2) { compDelta += 1; }
                else { ds.greenwashRisk += 5; }

                if (d.supplierInvest === 1) { esgDelta += 5; trustDelta += 2; finDelta += 0.5; }
                else if (d.supplierInvest === 2) { esgDelta += 1; }
                else { /* no change */ }

                if (d.governance === 1 && d.auditScope === 1) {
                    eventKey = 'event_2a';
                    compDelta -= 2;
                    esgDelta += 2;
                } else if (d.supplierInvest === 1) {
                    eventKey = 'event_2c';
                    esgDelta += 3;
                    finDelta += 0.3;
                } else {
                    eventKey = 'event_2b';
                    trustDelta -= 3;
                    finDelta -= 0.5;
                }
            }

            if (period === 3) {
                var prevAuthentic = ds.esgAuth >= 42;

                if (d.publicResponse === 1) {
                    if (prevAuthentic) { trustDelta += 6; finDelta += 0.5; }
                    else { trustDelta -= 2; ds.greenwashRisk += 10; }
                } else if (d.publicResponse === 2) {
                    trustDelta += 1;
                } else {
                    trustDelta -= 2;
                }

                if (d.investorOutreach === 1) { trustDelta += 3; finDelta += 0.8; }
                else if (d.investorOutreach === 2) { trustDelta += 1; }

                if (d.auditAccel === 1) { compDelta += 3; esgDelta += 2; }
                else if (d.auditAccel === 3) { ds.greenwashRisk += 10; }

                if (d.competitivePosture === 1) { esgDelta += 4; trustDelta += 3; }
                else if (d.competitivePosture === 3) { ds.greenwashRisk += 15; compDelta -= 3; }

                if (d.publicResponse === 1 && prevAuthentic) {
                    eventKey = 'event_3a';
                    finDelta += 1.0;
                    trustDelta += 3;
                } else if (d.competitivePosture === 3) {
                    eventKey = 'event_3c';
                    trustDelta -= 5;
                    ds.greenwashRisk += 10;
                } else {
                    eventKey = 'event_3b';
                    trustDelta -= 2;
                }
            }

            if (period === 4) {
                if (d.disclosureFindings === 1) {
                    trustDelta -= 5;
                    compDelta += 5;
                    esgDelta += 3;
                } else if (d.disclosureFindings === 2) {
                    trustDelta += 1;
                    ds.greenwashRisk += 15;
                } else {
                    ds.greenwashRisk += 25;
                }

                if (d.remediation === 1) { esgDelta += 5; trustDelta += 4; compDelta += 3; }
                else if (d.remediation === 2) { esgDelta += 3; }
                else { ds.greenwashRisk += 10; }

                if (d.thirdPartyVerify === 1) { trustDelta += 4; compDelta += 3; }
                else if (d.thirdPartyVerify === 2) { compDelta += 1; }
                else { ds.greenwashRisk += 5; }

                if (d.disclosureFindings === 1 && d.remediation === 1) {
                    eventKey = 'event_4a';
                    trustDelta += 4;
                } else if (d.disclosureFindings === 2) {
                    eventKey = 'event_4b';
                    trustDelta -= 15;
                    compDelta -= 5;
                    ds.greenwashRisk += 10;
                } else if (d.disclosureFindings === 3) {
                    eventKey = 'event_4c';
                    trustDelta -= 20;
                    compDelta -= 10;
                    ds.greenwashRisk += 20;
                } else {
                    eventKey = 'event_4a';
                    trustDelta += 2;
                }
            }

            if (period === 5) {
                var authScore = ds.esgAuth + esgDelta;
                var riskLevel = ds.greenwashRisk;

                if (d.coherence === 1) { esgDelta += 3; trustDelta += 4; }
                else if (d.coherence === 2) { trustDelta += 1; }
                else { ds.greenwashRisk += 10; }

                if (d.stakeholderEngage === 1) { trustDelta += 5; esgDelta += 2; }
                else if (d.stakeholderEngage === 2) { trustDelta += 1; }

                if (d.continuousImprove === 1) { esgDelta += 3; compDelta += 2; }

                if (d.esgFinance === 1) { finDelta += 1.5; trustDelta += 2; }
                else if (d.esgFinance === 2) { finDelta += 0.5; }

                if (d.publicCommit === 1) { trustDelta += 4; compDelta += 2; }
                else if (d.publicCommit === 2) { trustDelta += 1; }

                if (riskLevel < 20 && authScore >= 50) {
                    eventKey = 'event_5a';
                    trustDelta += 8;
                    finDelta += 1.0;
                } else if (riskLevel >= 50) {
                    eventKey = 'event_5c';
                    trustDelta -= 20;
                    compDelta -= 10;
                    finDelta -= 3.0;
                } else {
                    eventKey = 'event_5b';
                    trustDelta += 1;
                }
            }

            ds.esgAuth = Math.max(0, Math.min(100, ds.esgAuth + esgDelta));
            ds.regCompliance = Math.max(0, Math.min(100, ds.regCompliance + compDelta));
            ds.ebitdaImpact = Math.round((ds.ebitdaImpact + finDelta) * 10) / 10;
            ds.brandTrust = Math.max(0, Math.min(100, ds.brandTrust + trustDelta));

            ds.esgHistory.push(ds.esgAuth);
            ds.complianceHistory.push(ds.regCompliance);
            ds.financeHistory.push(ds.ebitdaImpact);
            ds.trustHistory.push(ds.brandTrust);

            if (eventKey) {
                ds.eventLog.push(eventKey);
                var eventPanel = document.getElementById('eventPanel');
                var eventText = document.getElementById('eventText');
                if (eventPanel && eventText && window.mySimulation) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = window.mySimulation.t(eventKey);
                }
            }

            var results = {
                period: period,
                esgAuth: ds.esgAuth,
                regCompliance: ds.regCompliance,
                ebitdaImpact: ds.ebitdaImpact,
                brandTrust: ds.brandTrust,
                budgetSpent: cost,
                budgetRemaining: ds.budgetRemaining,
                esgDelta: esgDelta,
                compDelta: compDelta,
                finDelta: finDelta,
                trustDelta: trustDelta,
                eventKey: eventKey
            };

            this._dsSnaps[period] = JSON.parse(JSON.stringify(ds));

            if (period < this.ROUNDS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }

            return results;
        }

