        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastRecord = history[history.length - 1];
            var r = lastRecord.results || {};

            var esgNorm = (r.esgAuth || 35) / 100;
            var compNorm = (r.regCompliance || 85) / 100;
            var finNorm = Math.max(0, Math.min(1, ((r.ebitdaImpact || 0) + 10) / 15));
            var trustNorm = (r.brandTrust || 52) / 100;

            var composite = (esgNorm * 0.30 + compNorm * 0.25 + finNorm * 0.25 + trustNorm * 0.20) * 100;

            var performance = 'Greenwasher';
            if (composite > 75) performance = 'ESG Champion';
            else if (composite > 60) performance = 'Authentic Leader';
            else if (composite > 45) performance = 'Pragmatic Balancer';
            else if (composite > 30) performance = 'Compliance Minimalist';

            var insights = [];
            if (r.esgAuth >= 55) insights.push('Strong substantive ESG improvements drove real change.');
            if (r.esgAuth < 40) insights.push('Limited genuine ESG improvement — disclosure outpaced substance.');
            if (r.regCompliance >= 85) insights.push('Maintained strong regulatory compliance throughout.');
            if (r.regCompliance < 60) insights.push('Regulatory risk is elevated due to aggressive disclosure choices.');
            if (r.brandTrust >= 65) insights.push('Stakeholders trust the ESG commitment — credibility is high.');
            if (r.brandTrust < 35) insights.push('Brand trust collapsed — greenwashing exposure damaged reputation.');
            if (r.ebitdaImpact > 0) insights.push('Positive financial returns from ESG-linked financing strategies.');
            if (r.ebitdaImpact < -5) insights.push('Heavy investment costs impacted short-term financial performance.');

            return {
                compositeScore: Math.round(composite),
                esgAuth: r.esgAuth,
                regCompliance: r.regCompliance,
                ebitdaImpact: r.ebitdaImpact,
                brandTrust: r.brandTrust,
                performance: performance,
                insights: insights
            };
        }

